using System;using System.IO;using System.Reflection;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using Demo6.Game;
public static class V5InputProbe{public static async Task<object> Run(){var p=PlayerController.Instance;var input=p.GetComponent<PlayerInputReader>();var oldK=Keyboard.current;var oldM=Mouse.current;var k=InputSystem.AddDevice<Keyboard>("V5Key");var m=InputSystem.AddDevice<Mouse>("V5Mouse");var bg=InputSystem.settings.backgroundBehavior;bool run=Application.runInBackground;var rows=new List<object>();var position=p.Position;try{Application.runInBackground=true;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.EnableDevice(k);InputSystem.EnableDevice(m);for(int i=0;i<12;i++){k.MakeCurrent();m.MakeCurrent();InputSystem.QueueStateEvent(k,new KeyboardState(Key.D));InputSystem.QueueStateEvent(m,new MouseState{position=new Vector2(Screen.width*.7f,Screen.height*.5f)});await Task.Delay(70);rows.Add(new{i,key=k.dKey.isPressed,k.enabled,mouse=m.position.ReadValue().ToString(),currentKey=Keyboard.current.name,currentMouse=Mouse.current.name,move=input.Move.ToString(),pos=p.Position.ToString(),pose=p.Pose.ToString(),down=p.IsDown,paused=TimeScaleService.Paused,blocked=PlayerInputReader.Blocked,focus=Application.isFocused});}}finally{InputSystem.RemoveDevice(k);InputSystem.RemoveDevice(m);oldK?.MakeCurrent();oldM?.MakeCurrent();InputSystem.settings.backgroundBehavior=bg;Application.runInBackground=run;p.Teleport(position);Camera.main.GetComponent<DungeonCamera>().Snap();}File.WriteAllText("검증/플레이-사용성-v5/input-diagnostic.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows));return rows;}}
